interface A { default void log() { System.out.println("A"); } }
interface B { default void log() { System.out.println("B"); } }

public class Diamond implements A, B {
    @Override
    public void log() {
        // Explicitly resolve the diamond conflict
        A.super.log();
        B.super.log();
        System.out.println("Resolved");
    }
}
